for p,row in (status.get('providers') or {}).items():
    print('PROVIDER',p,'target',row.get('target_concurrency'),'active',row.get('active'),'success',row.get('successes'),'429',row.get('rate_limits'),'errors',row.get('errors'))
    mh=row.get('model_health') or {}
    for m,h in mh.items():
        if m in {'nvidia/nemotron-3-super-120b-a12b','nvidia/nemotron-3-ultra-550b-a55b','nvidia/nemotron-mini-4b-instruct','openai/gpt-oss-20b','qwen/qwen3.6-27b'}:
            print('HEALTH',p,m,'disabled',h.get('disabled'),'weight',h.get('routing_weight'),'success',h.get('success'),'hard4xx',h.get('hard_4xx'),'5xx',h.get('transient_5xx'),'delta',h.get('delta_markers'),'accepted',h.get('accepted_deltas'),'lat',h.get('latency_ema_s'))
counts=collections.Counter(); ok=collections.Counter(); delta=collections.Counter()
if (run/'workers.jsonl').exists():
    for line in (run/'workers.jsonl').open(errors='replace'):
        try:o=json.loads(line)
        except:continue
        k=(o.get('provider'),o.get('model')); counts[k]+=1
        s=o.get('http_status')
        if isinstance(s,int) and 200<=s<300: ok[k]+=1
        if (o.get('conformance') or {}).get('architecture_delta_marker'): delta[k]+=1
print('RUN_COUNTS')
for k,n in counts.most_common(): print(k,'total',n,'ok',ok[k],'delta',delta[k])
forge=root/'forge/STATUS.json'
if forge.exists():
    f=json.loads(forge.read_text()); print('FORGE_ACCEPTED',f.get('accepted_deltas'),'EVALS',f.get('evaluations'),'STATES',f.get('candidate_states'))
